input.sparql:
SELECT DISTINCT ?entity ?name WHERE {
  ?entity a brick:ElectricPower .
  FILTER regex(str(?entity), "whole-building|WholeBuilding|building", "i")
  ?entity rdfs:label ?name .
}

SELECT DISTINCT ?point ?name ?ts WHERE {
  ?point ref:hasTimeseriesId ?ts .
  OPTIONAL { ?point rdfs:label ?name } .
} LIMIT 50

SELECT ?p ?ts ?bldg WHERE {
  ?p a brick:Electric_Power_Sensor .
  OPTIONAL { ?p brick:hasAnInput ?bldg . }
  OPTIONAL { ?p ref:hasTimeseriesId ?ts . }
}
